style.css:
@-moz-document domain("youtube.com") {
/* === Neon Hacklord Progress Bar === */
    .ytp-progress-bar,         /* full bar track */
    .ytp-load-progress,        /* loaded portion */
    .ytp-hover-progress {      /* hover preview */
        background-color: #000 !important; /* black background track */
    }

    .ytp-play-progress {
        background-color: #39FF14 !important;  /* neon green fill */
        box-shadow: 0 0 5px #39FF14, 0 0 10px #39FF14, 0 0 15px #39FF14 !important; /* glow */
    }

    /* === Progress bar handle/knob === */
    .ytp-progress-bar-container .ytp-progress-thumb {
        border: 2px solid #39FF14 !important;  /* neon green knob border */
        box-shadow: 0 0 5px #39FF14, 0 0 10px #39FF14, 0 0 15px #39FF14 !important; /* glow effect */
        background-color: #000 !important;      /* black center for contrast */
    }

    /* === Tooltip/hover time preview glow === */
    .ytp-tooltip {
        text-shadow: 0 0 2px #39FF14, 0 0 5px #39FF14 !important;
        color: #39FF14 !important;
        font-family: 'Accanthis ADF Std', serif !important;
    }
}
